#include <afterlight/physics.h>
#include <stdio.h>
#include <math.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"Landing %d: %s\n",__LINE__,#x);return 1;}}while(0)
static af_object_id box(af_scene *s,af_vec3 pos,af_vec3 half,bool dynamic){af_object_id id=af_scene_add_object(s,"Box","cube");af_transform t=af_transform_identity();t.position=pos;af_collider c=af_collider_default();c.type=AF_COLLIDER_BOX;c.half_extents=half;af_scene_set_object_transform(s,id,t);af_scene_set_object_collider(s,id,c);if(dynamic){af_rigid_body b=af_rigid_body_default();b.enabled=true;b.type=AF_BODY_DYNAMIC;b.continuous=true;af_scene_set_body(s,id,b);}return id;}
int main(void){for(unsigned offset=0;offset<3;++offset){af_scene *s=af_scene_create();af_physics *p=af_physics_create();box(s,(af_vec3){0,-.5f,0},(af_vec3){10,.5f,10},false);af_object_id crate=box(s,(af_vec3){0,.5f,0},(af_vec3){.5f,.5f,.5f},true),player=af_scene_add_object(s,"Player","__node");af_character_config config=af_character_config_default();af_collider c=af_collider_default();c.type=AF_COLLIDER_CAPSULE;c.radius=config.radius;c.half_height=config.half_height;CHECK(af_scene_set_object_collider(s,player,c));af_gameplay_component g=af_gameplay_component_default();g.player.enabled=true;CHECK(af_scene_set_object_gameplay(s,player,g));af_character ch={.position={offset==0?0:offset==1?.65f:.65f,4,offset==2?.65f:0}};af_transform t=af_transform_identity();t.position=ch.position;CHECK(af_scene_set_object_transform(s,player,t));float speed=0,spin=0;for(unsigned tick=0;tick<360;++tick){CHECK(af_character_step(s,&ch,config,(af_character_input){.jump=tick==150},1.f/60,(af_query_filter){.ignore=player,.mask=UINT32_MAX}));t.position=ch.position;CHECK(af_scene_set_object_transform(s,player,t)&&af_physics_step(p,s,1.f/60));af_physics_state b=af_physics_get_state(p,crate);speed=fmaxf(speed,sqrtf(b.velocity.x*b.velocity.x+b.velocity.z*b.velocity.z));spin=fmaxf(spin,af_vec3_length(b.angular_velocity));}printf("landing %u: horizontal %.3f spin %.3f\n",offset,speed,spin);CHECK(speed<.8f&&spin<1.5f);af_scene_destroy(s);af_physics_destroy(p);}return 0;}
